import React, { useState } from "react";
import "./BudgetLimits.css";

function BudgetLimits() {
  const [limits, setLimits] = useState({
    "Food & Groceries": "",
    Shopping: "",
    Bills: "",
    Health: "",
    Entertainment: "",
    Transport: ""
  });

  const handleChange = (category, value) => {
    setLimits({
      ...limits,
      [category]: value
    });
  };

  const handleSave = () => {
    alert("Budget limits saved successfully!");
  };

  return (
    <div className="questionnaire-container">
      <div className="questionnaire-card">

        <h2 className="questionnaire-title">
          Set Monthly Budget Limits
        </h2>

        {Object.keys(limits).map((category) => (
          <div className="form-group" key={category}>
            <label className="form-label">{category}</label>

            <input
              type="number"
              className="form-input"
              placeholder="Enter amount"
              value={limits[category]}
              onChange={(e) =>
                handleChange(category, e.target.value)
              }
            />
          </div>
        ))}

        <button className="next-button" onClick={handleSave}>
          Save Limits
        </button>

      </div>
    </div>
  );
}

export default BudgetLimits;
